/**
 * Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
 * @return the size of the message
 */
public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    writeRawVarint32(size, out);
    return size + writeTo(out, message, schema, buffer);
}

private static void writeRawVarint32(int value, OutputStream out) throws IOException {
    while (true) {
        if ((value & ~0x7F) == 0) {
            out.write(value);
            return;
        } else {
            out.write((value & 0x7F) | 0x80);
            value >>>= 7;
        }
    }
}

private static <T> int writeTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    if (buffer.start != buffer.offset) {
        throw new IOException("Buffer is not fresh");
    }
    if (size <= buffer.buffer.length - buffer.offset) {
        schema.writeTo(message, buffer);
        out.write(buffer.buffer, buffer.start, buffer.offset - buffer.start);
        buffer.reset();
        return size;
    } else {
        LinkedBuffer newBuffer = LinkedBuffer.allocate(size);
        schema.writeTo(message, newBuffer);
        LinkedBuffer.writeTo(out, buffer);
        LinkedBuffer.writeTo(out, newBuffer);
        buffer.reset();
        newBuffer.clear();
        return size;
    }
}

