public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int i = 0;
    int len = str.length();

    while (i < len) {
        char c = str.charAt(i);

        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'n':
                        sb.append('\n');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    default:
                        throw new Exception("Invalid escape sequence: \\" + nextChar);
                }
                i += 2; // Skip the next character as it's part of the escape sequence
            } else {
                throw new Exception("Invalid escape sequence at the end of the string");
            }
        } else {
            sb.append(c);
            i++;
        }
    }

    return sb.toString();
}

