private void pop(final String descriptor) {
    // Check if the descriptor is a method descriptor
    if (descriptor.charAt(0) == '(') {
        // Find the closing parenthesis of the method descriptor
        int closingParenthesisIndex = descriptor.indexOf(')');
        // Extract the argument types from the descriptor
        String argumentTypes = descriptor.substring(1, closingParenthesisIndex);
        // Pop each argument type from the stack
        for (int i = 0; i < argumentTypes.length(); i++) {
            popSingleType(argumentTypes.charAt(i));
        }
    } else {
        // If it's a single type descriptor, pop it directly
        popSingleType(descriptor.charAt(0));
    }
}

private void popSingleType(char type) {
    switch (type) {
        case 'B': // byte
        case 'C': // char
        case 'I': // int
        case 'S': // short
        case 'Z': // boolean
            // These types occupy one slot
            outputFrameStack.pop();
            break;
        case 'J': // long
        case 'D': // double
            // These types occupy two slots
            outputFrameStack.pop();
            outputFrameStack.pop();
            break;
        case 'F': // float
            // This type occupies one slot
            outputFrameStack.pop();
            break;
        case 'L': // object
            // Find the closing semicolon of the object descriptor
            int closingSemicolonIndex = descriptor.indexOf(';');
            // Pop the object reference
            outputFrameStack.pop();
            break;
        case '[': // array
            // Pop the array reference
            outputFrameStack.pop();
            break;
        default:
            throw new IllegalArgumentException("Invalid type descriptor: " + type);
    }
}

