public static String applyRelativePath(String path, String relativePath) {
    // Normalize the paths to ensure they use the correct separator
    path = path.replace("\\", "/");
    relativePath = relativePath.replace("\\", "/");

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a stack to handle the path components
    Stack<String> stack = new Stack<>();

    // Push all components of the base path onto the stack
    for (String component : pathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            stack.push(component);
        }
    }

    // Process each component of the relative path
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!component.isEmpty() && !component.equals(".")) {
            stack.push(component);
        }
    }

    // Build the resulting path from the stack
    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        result.insert(0, stack.pop());
        if (!stack.isEmpty()) {
            result.insert(0, "/");
        }
    }

    return result.toString();
}

