public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;

    while ((line = reader.readLine()) != null) {
        // Assuming each line contains a timestamp and thread snapshot data
        String[] parts = line.split("\\s+");
        if (parts.length < 2) {
            continue; // Skip invalid lines
        }

        long timestamp = Long.parseLong(parts[0]);
        String snapshotData = line.substring(parts[0].length()).trim();

        // Check if the timestamp falls within any of the provided time ranges
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, snapshotData);
                snapshots.add(snapshot);
                break; // No need to check other time ranges if a match is found
            }
        }
    }

    reader.close();
    return snapshots;
